import{_ as t,o as a,c as i,a2 as o}from"./chunks/framework.D9E58p8B.js";const h=JSON.parse('{"title":"Confidentialité","description":"","frontmatter":{"title":"Confidentialité"},"headers":[],"relativePath":"guide/confidentialite.md","filePath":"guide/confidentialite.md"}'),s={name:"guide/confidentialite.md"};function n(r,e,l,c,u,d){return a(),i("div",null,[...e[0]||(e[0]=[o('<h1 id="confidentialite" tabindex="-1">Confidentialité <a class="header-anchor" href="#confidentialite" aria-label="Permalink to &quot;Confidentialité&quot;">​</a></h1><h2 id="tout-est-local" tabindex="-1">Tout est local <a class="header-anchor" href="#tout-est-local" aria-label="Permalink to &quot;Tout est local&quot;">​</a></h2><p>Daimon tourne sur votre ordinateur. Il n&#39;a ni télémétrie ni compte et ne collecte rien. Il n&#39;appelle lui-même aucun modèle d&#39;IA et n&#39;envoie rien à ArboRithm.</p><p>Sa seule connexion à Internet est la vérification des mises à jour, servie par GitHub Releases. Si l&#39;outil GitHub CLI (<code>gh</code>) est installé et connecté, cette vérification lui demande aussi, avec votre propre session, si votre compte a accès au canal de mise à jour réservé d&#39;ArboRithm : rien n&#39;est transmis à ArboRithm.</p><h2 id="ce-site-de-documentation" tabindex="-1">Ce site de documentation <a class="header-anchor" href="#ce-site-de-documentation" aria-label="Permalink to &quot;Ce site de documentation&quot;">​</a></h2><p>Ce site mesure son audience avec Matomo, hébergé par ArboRithm, <strong>sans cookie</strong> : il compte les pages vues, sans rien déposer chez vous. Cela concerne ce site uniquement ; l&#39;application Daimon, elle, n&#39;envoie rien à ArboRithm.</p><h2 id="ce-que-fait-votre-client-ia" tabindex="-1">Ce que fait votre client IA <a class="header-anchor" href="#ce-que-fait-votre-client-ia" aria-label="Permalink to &quot;Ce que fait votre client IA&quot;">​</a></h2><p>Ce que votre client IA fait de ce qu&#39;il perçoit à travers Daimon (une capture d&#39;écran, le texte d&#39;une fenêtre) se joue entre vous et le fournisseur de ce client. Réglez le <a href="./plafond-et-exclusions.html">plafond</a> et vos exclusions en conséquence.</p><h2 id="les-secrets" tabindex="-1">Les secrets <a class="header-anchor" href="#les-secrets" aria-label="Permalink to &quot;Les secrets&quot;">​</a></h2><ul><li>Les champs de mot de passe sont masqués dans ce que l&#39;IA lit de l&#39;arbre d&#39;accessibilité.</li><li>Dans les captures d&#39;écran, ils sont noircis aussi lorsque l&#39;arbre d&#39;accessibilité est lisible (sous macOS, une fois l&#39;autorisation Accessibilité accordée). C&#39;est une passe faite au mieux : le résultat le signale quand elle n&#39;a pas pu avoir lieu.</li><li>Vos propres <a href="./plafond-et-exclusions.html#les-exclusions">exclusions</a> s&#39;ajoutent : applications refusées, zones noircies, titres retirés.</li></ul><h2 id="le-journal-d-activite" tabindex="-1">Le journal d&#39;activité <a class="header-anchor" href="#le-journal-d-activite" aria-label="Permalink to &quot;Le journal d&#39;activité&quot;">​</a></h2><p>Chaque action des Mains est inscrite, sur votre ordinateur, dans un journal dont toute altération se détecte (chaque entrée est chaînée à la précédente). Il consigne ce qui a été fait et sur quoi, <strong>jamais le texte saisi</strong>. Le bouton <strong>Journal d&#39;activité</strong> du panneau ouvre son dossier.</p><h2 id="ou-sont-les-fichiers" tabindex="-1">Où sont les fichiers <a class="header-anchor" href="#ou-sont-les-fichiers" aria-label="Permalink to &quot;Où sont les fichiers&quot;">​</a></h2><p>Les réglages (<code>exclusions.yaml</code>, <code>update.yaml</code>) sont dans le dossier de configuration, que le panneau ouvre. Le dossier de données par défaut est <code>~/Library/Application Support/Daimon</code> sous macOS et <code>%APPDATA%\\Daimon</code> sous Windows ; la configuration y est dans <code>config</code> et les journaux dans <code>logs</code>.</p>',14)])])}const m=t(s,[["render",n]]);export{h as __pageData,m as default};
